/* Trigger structure for table `compradores` */

DELIMITER $$

/*!50003 DROP TRIGGER*//*!50032 IF EXISTS */ /*!50003 `tr_sync_usuario_persona` */$$

/*!50003 CREATE */ /*!50017 DEFINER = 'root'@'localhost' */ /*!50003 TRIGGER `tr_sync_usuario_persona` AFTER INSERT ON `compradores` FOR EACH ROW BEGIN
    UPDATE personas 
    SET usuario_id = NEW.usuario_id,
