/* Trigger structure for table `personas` */

DELIMITER $$

/*!50003 DROP TRIGGER*//*!50032 IF EXISTS */ /*!50003 `tr_personas_log_update` */$$

/*!50003 CREATE */ /*!50017 DEFINER = 'root'@'localhost' */ /*!50003 TRIGGER `tr_personas_log_update` AFTER UPDATE ON `personas` FOR EACH ROW BEGIN
    INSERT INTO log_personas (
        id_persona,
        nombres,
        apellidos,
        telefono,
        direccion,
        fecha_nacimiento,
        eliminado_por,
        fecha_eliminacion,
        fecha_modificacion,
        fecha_ingreso,
        ciudad_id,
        tipo_persona,
        razon_social,
        operacion
    )
    VALUES (
        OLD.id_persona,
        OLD.nombres,
        OLD.apellidos,
        OLD.telefono,
        OLD.direccion,
        OLD.fecha_nacimiento,
        COALESCE(NULLIF(@usuario_actual, ''), 'SISTEMA'), -- Usuario que hace la edición
        NULL,
        NOW(), -- Fecha de modificación
        OLD.fecha_ingreso,
        OLD.ciudad_id,
        OLD.tipo_persona,
        OLD.razon_social,
        'UPDATE'
    );
END */$$


DELIMITER ;

