/* Trigger structure for table `usuarios` */

DELIMITER $$

/*!50003 DROP TRIGGER*//*!50032 IF EXISTS */ /*!50003 `tr_desactivar_vendedor_cascada` */$$

/*!50003 CREATE */ /*!50017 DEFINER = 'root'@'localhost' */ /*!50003 TRIGGER `tr_desactivar_vendedor_cascada` AFTER UPDATE ON `usuarios` FOR EACH ROW BEGIN
    -- Desactivar vendedor si usuario se desactiva
    IF OLD.estado = 1 AND NEW.estado = 0 THEN
        UPDATE vendedores
        SET activo = FALSE
        WHERE usuario_id = NEW.id_usuario;
    END IF;
    -- Reactivar vendedor si usuario se reactiva
    IF OLD.estado = 0 AND NEW.estado = 1 THEN
        UPDATE vendedores
        SET activo = TRUE
        WHERE usuario_id = NEW.id_usuario;
    END IF;
END */$$


DELIMITER ;

/* Procedure structure for procedure `sp_actualizarUsuario` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_actualizarUsuario` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_actualizarUsuario`(
    IN p_id INT,
    IN p_usuario VARCHAR(50),
    IN p_clave VARCHAR(255),
    IN p_estado BOOLEAN,
    IN p_rol VARCHAR(20),
    IN p_usuario_modificador VARCHAR(50)
)
BEGIN
    INSERT INTO log_usuarios (id_usuario, usuario, clave, rol, estado, modificado_por, fecha_modificacion)
    SELECT id_usuario, usuario, clave, rol, estado, p_usuario_modificador, NOW()
    FROM usuarios
    WHERE id_usuario = p_id;
    UPDATE usuarios
    SET usuario = p_usuario,
        clave = p_clave,
        estado = p_estado,
        rol = p_rol
    WHERE id_usuario = p_id;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_buscarUsuarioPorNombre` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_buscarUsuarioPorNombre` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_buscarUsuarioPorNombre`(
    IN p_usuario VARCHAR(50)
)
BEGIN
    SELECT id_usuario, usuario, clave, rol, estado, fecha_alta, id_persona
    FROM usuarios
    WHERE usuario = p_usuario
    LIMIT 1;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_cambiarClaveUsuario` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_cambiarClaveUsuario` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_cambiarClaveUsuario`(
    IN p_id_usuario INT,
    IN p_nueva_clave VARCHAR(255),
    IN p_usuario_modificador VARCHAR(50)
)
BEGIN
    UPDATE usuarios
    SET clave = p_nueva_clave
    WHERE id_usuario = p_id_usuario;
    SELECT ROW_COUNT() AS filas_afectadas;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_cambiarRolUsuario` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_cambiarRolUsuario` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_cambiarRolUsuario`(
    IN p_id INT,
    IN p_rol VARCHAR(20),
    IN p_estado BOOLEAN,
    IN p_usuario_modificador VARCHAR(50)
)
BEGIN
    DECLARE v_persona_id INT;
    DECLARE v_codigo_vendedor VARCHAR(50);
    -- 1. Registrar log antes de modificar
    INSERT INTO log_usuarios (id_usuario, usuario, clave, rol, estado, modificado_por, fecha_modificacion)
    SELECT id_usuario, usuario, clave, rol, estado, p_usuario_modificador, NOW()
    FROM usuarios
    WHERE id_usuario = p_id;
    -- 2. Actualizar rol y estado
    UPDATE usuarios
    SET rol = p_rol,
        estado = p_estado
    WHERE id_usuario = p_id;
    -- 3. Obtener el id_persona (Aquí es donde fallaba Antonio)
    SELECT id_persona INTO v_persona_id
    FROM usuarios
    WHERE id_usuario = p_id;
    -- 4. Lógica de Vendedores (Solo si v_persona_id NO es nulo)
    IF v_persona_id IS NOT NULL THEN
        IF p_rol = 'VENDEDOR' THEN
            SELECT codigo_vendedor INTO v_codigo_vendedor
            FROM vendedores
            WHERE persona_id = v_persona_id
            LIMIT 1;
            IF v_codigo_vendedor IS NOT NULL THEN
                UPDATE vendedores
                SET activo = TRUE, usuario_id = p_id -- Aseguramos el vínculo del usuario
                WHERE persona_id = v_persona_id;
            ELSE
                INSERT INTO vendedores (persona_id, usuario_id, codigo_vendedor, activo)
                VALUES (v_persona_id, p_id, CONCAT('VEND-', p_id, '-', UNIX_TIMESTAMP()), TRUE);
            END IF;
        ELSE
            -- Desactivar si deja de ser vendedor
            UPDATE vendedores
            SET activo = FALSE
            WHERE persona_id = v_persona_id;
        END IF;
    END IF;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_cierre_compras` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_cierre_compras` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_cierre_compras`(
    IN p_fechaCierre DATE
)
BEGIN
    UPDATE compras
    SET estado = 'CERRADA'
    WHERE fecha <= p_fechaCierre AND estado <> 'CERRADA';
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_cuentas_vencidas` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_cuentas_vencidas` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_cuentas_vencidas`(
    IN p_fechaActual DATE
)
BEGIN
    SELECT *
    FROM cuentas_pagar
    WHERE fecha_vencimiento < p_fechaActual AND estado = 'PENDIENTE';
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_eliminarPersona` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_eliminarPersona` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_eliminarPersona`(
    IN p_id BIGINT,
    IN p_usuario VARCHAR(50)
)
BEGIN
    -- Pasar usuario a la sesión para triggers
    SET @usuario_actual = p_usuario;
    -- Validar si la persona tiene usuario asociado
    IF EXISTS (
        SELECT 1
        FROM personas
        WHERE id_persona = p_id
          AND (usuario_id IS NOT NULL OR usuario_asociado_id IS NOT NULL)
    ) THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'No se puede eliminar la persona porque tiene un usuario asociado';
    END IF;
    -- Insertar en log antes de borrar
    INSERT INTO log_personas (
        id_persona,
        nombres,
        apellidos,
        telefono,
        direccion,
        fecha_nacimiento,
        eliminado_por,
        fecha_eliminacion,
        fecha_ingreso,
        ciudad_id,
        tipo_persona,
        razon_social,
        operacion
    )
    SELECT
        id_persona,
        nombres,
        apellidos,
        telefono,
        direccion,
        fecha_nacimiento,
        p_usuario,
        NOW(),
        fecha_ingreso,
        ciudad_id,
        tipo_persona,
        razon_social,
        'DELETE'
    FROM personas
    WHERE id_persona = p_id;
    -- DELETE físico
    DELETE FROM personas
    WHERE id_persona = p_id;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_eliminarUsuario` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_eliminarUsuario` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_eliminarUsuario`(
    IN p_id INT,
    IN p_usuario_modificador VARCHAR(50)
)
BEGIN
    DECLARE existeVendedor INT;
    -- Verificar si el usuario tiene un vendedor asociado
    SELECT COUNT(*) INTO existeVendedor
    FROM vendedores
    WHERE usuario_id = p_id;
    -- Registrar log antes de cualquier acción
    INSERT INTO log_usuarios (id_usuario, usuario, clave, rol, estado, modificado_por, fecha_modificacion)
    SELECT id_usuario, usuario, clave, rol, estado, p_usuario_modificador, NOW()
    FROM usuarios
    WHERE id_usuario = p_id;
    IF existeVendedor > 0 THEN
        -- Solo desactivar usuario
        UPDATE usuarios
        SET estado = FALSE
        WHERE id_usuario = p_id;
    ELSE
        -- Usuario sin vendedor, se puede eliminar
        DELETE FROM usuarios
        WHERE id_usuario = p_id;
    END IF;
    -- Retornar número de filas afectadas
    SELECT ROW_COUNT() AS filas_afectadas;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_insertarUsuario` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_insertarUsuario` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_insertarUsuario`(
    IN p_usuario VARCHAR(50),
    IN p_clave VARCHAR(255),
    IN p_estado BOOLEAN,
    IN p_rol VARCHAR(20),
    IN p_id_persona INT
)
BEGIN
    DECLARE nuevo_usuario_id BIGINT;
    -- 1. Insertar el usuario en la tabla usuarios
    INSERT INTO usuarios(usuario, clave, estado, rol, id_persona)
    VALUES(p_usuario, p_clave, p_estado, p_rol, p_id_persona);
    -- 2. Obtener el ID generado
    SET nuevo_usuario_id = LAST_INSERT_ID();
    -- 3. Actualizar la persona vinculada
    -- Aquí marcamos usuario_asociado_id Y TAMBIÉN el rol de vendedor si corresponde
    UPDATE personas
    SET usuario_asociado_id = nuevo_usuario_id,
        es_vendedor = IF(p_rol = 'VENDEDOR', 1, es_vendedor)
    WHERE id_persona = p_id_persona;
    -- 4. Retornar el ID del nuevo usuario
    SELECT nuevo_usuario_id AS id_usuario;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_libro_compras_proveedor` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_libro_compras_proveedor` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_libro_compras_proveedor`(
    IN p_proveedorId BIGINT
)
BEGIN
    SELECT lc.id,
           lc.timbrado,
           lc.numero_factura,
           lc.base_imponible,
           lc.iva_credito,
           lc.total_factura,
           c.fecha AS fecha_compra,
           p.razon_social AS proveedor
    FROM libro_compras lc
    INNER JOIN compras c ON lc.compra_id = c.id
    INNER JOIN proveedores p ON c.proveedor_id = p.id
    WHERE p.id = p_proveedorId;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_listarPersonasSinUsuario` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_listarPersonasSinUsuario` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_listarPersonasSinUsuario`()
BEGIN
    SELECT *
    FROM personas
    -- Solo personas que NO tengan creador Y NO tengan asociado Y NO sean vendedores
    WHERE (usuario_id IS NULL OR usuario_id = 0)
      AND (usuario_asociado_id IS NULL OR usuario_asociado_id = 0)
      AND es_vendedor = 0;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_listarUsuario` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_listarUsuario` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_listarUsuario`()
BEGIN
    SELECT 
        u.id_usuario, 
        u.usuario, 
        u.clave, 
        u.rol, 
        u.estado, 
        u.fecha_alta, 
        u.id_persona,
        p.nombres,
        p.apellidos
    FROM usuarios u
    LEFT JOIN personas p ON u.id_persona = p.id_persona;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_listarUsuarioSeguro` */

